#[using="Type"] Lemma art_refill_fp_out_img : forall sp HI t spb ris qs c km x, 1 <= c <= 30 -> HI <= sp - 720 -> 0x10007fff8000 <= HI -> spb = 65536 * qs -> 0x10007fff8000 <= spb -> ris = spb + 2 ^ 37 ->
