Definition art_enq_tail_W (t b L B : Z) : list (Z * Z) :=
  [ (t + 208 + 1920, 4); (t + 208 + 2576, 8); (b, 32); ((if L =? 0 then t + 80 + 8 else B), 8); (t + 80, 8); (t + 96, 16) ].

