#[using="Type"] Lemma art_refill_fp_out64 : forall sp HI t spb ris qs km x, HI <= sp - 736 -> sp < 2 ^ 47 -> spb = 65536 * qs -> 0x10007fff8000 <= spb -> ris = spb + 2 ^ 37 -> ris + 4096 <= HI ->
  4096 <= t -> t + 4096 <= HI -> apart t 4096 spb (2 ^ 37 + 4096) -> apart t 4096 0x7fff7000 (0x10007fff8000 - 0x7fff7000) -> apart t 4096 0x10000 (0x6b6000 - 0x10000) ->
  0 <= km -> 262144 * km <= 3758096384 ->
  (sp - 64 <= x < sp) \/ (t + 208 + 2576 <= x < t + 208 + 2584) \/ (t + 80 <= x < t + 112) \/ (0x10000 <= x < 0x6b6000) -> ~ art_refill_fp (sp - 64) t spb ris qs 24 km x.
Proof.
