    0 <= loff -> 0x10000 <= tp + loff -> tp + loff + 4 <= 0x6b6000 -> 0x681968 <= tp - 88 -> 0x681968 <= tsd ->     (* [comment removed for export] *)
    (* [comment removed for export] *)
